git archive "$head" | tar -xf - -C "$d"
test -f "$d/artifacts/bot/scripts/ensureStickerTopicPin.ts" || { echo STK04_SOURCE_MISSING; exit 69; }
sudo -n docker build -q -f "$d/artifacts/bot/deploy/Dockerfile.gaybbs" -t "gace-stk04-pin:${head%%????????????????????????????????}" "$d" || { echo STK04_BUILD_FAILED; exit 70; }
sudo -n docker image inspect "gace-stk04-pin:${head%%????????????????????????????????}" --format '{{.Id}}' >/dev/null || { echo STK04_IMAGE_NOT_PRESENT; exit 71; }
printf 'STK04_PRODUCTION_IMAGE=BUILT\nSTK04_SOURCE_SHA=%s\n' "$head"
